// HasCoachingSessions applies the HasEdge predicate on the "coaching_sessions" edge.
func HasCoachingSessions() predicate.PromptTemplate {
	return predicate.PromptTemplate(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, CoachingSessionsTable, CoachingSessionsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCoachingSessionsWith applies the HasEdge predicate on the "coaching_sessions" edge with a given conditions (other predicates).
func HasCoachingSessionsWith(preds ...predicate.CoachingSession) predicate.PromptTemplate {
	return predicate.PromptTemplate(func(s *sql.Selector) {
		step := newCoachingSessionsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

